insert into website_settings (key, value) values ('business', '{"name":"Love Over Coffee — Vijay Nagar","short_name":"Love Over Coffee","address_lines":["Plot No. 11, Scheme No. 51, Scheme No. 113","Vijay Nagar"],"locality":"Vijay Nagar","city":"Indore","region":"Madhya Pradesh","postal_code":"452010","country":"IN","phone_display":"+91 93296 97769","phone_e164":"+919329697769","whatsapp_e164":"+919329697769","whatsapp_messages":{"general":"Hello Love Over Coffee! I''d like to know more about your menu and services.","reservation":"Hello Love Over Coffee! I''d like to enquire about reserving a table.","ordering":"Hello Love Over Coffee! I''d like to enquire about placing an order.","group":"Hello Love Over Coffee! I''d like to enquire about visiting with a group."},"email":null,"instagram_url":null,"maps_query":"Love Over Coffee, Plot No. 11, Scheme No. 113, Vijay Nagar, Indore 452010","maps_place_url":"https://www.google.com/maps/search/?api=1&query=Love+Over+Coffee+Scheme+113+Vijay+Nagar+Indore","geo":null,"price_range":"₹200–₹400 per person","hours":null,"hours_verification":"owner_to_confirm","rating_note":"Rated 4.7 on Google by around 1,000 guests","fssai":null}'::jsonb) on conflict (key) do nothing;
