insert into website_settings (key, value) values ('content', '{"hero_headline":"Good Coffee. Great Company. A Little More Love.","hero_image_url":null,"hero_subhead":"Your favourite corner for coffee, conversations, comfort food and unforgettable little moments.","intro_headline":"More Than Just Coffee.","intro_body":"Love Over Coffee is where the day slows down. Come for a carefully made cup, stay for comforting plates, a board game, and the kind of conversation that runs longer than planned.","reservation_headline":"Your Table Is Waiting.","reservation_body":"Planning a coffee date, catching up with friends, or simply taking a break? Reserve your favourite spot.","announcement":null,"story_sections":[{"id":"experience","title":"The Love Over Coffee experience","body":"A warm room, an easy pace, and a cup that is worth sitting with. We built this corner of Vijay Nagar for the moments in between — the catch-ups, the first dates, the long afternoons with a laptop.","needs_owner_review":true},{"id":"coffee","title":"Our approach to coffee","body":"From the everyday cappuccino to the indulgent Biscoff and dark-chocolate frappes, the menu is built around coffee that rewards slowing down.","needs_owner_review":true},{"id":"food","title":"Food and flavours","body":"Comfort food with Italian and Mexican accents — loaded nachos, pull-apart garlic bread, penne in rich sauces, and desserts made for sharing.","needs_owner_review":true},{"id":"ambience","title":"Our ambience","body":"A deep navy ceiling, blush velvet chairs, green sofas and a wall of books. A space designed to feel like a favourite room rather than a waiting room.","needs_owner_review":true},{"id":"conversations","title":"A place for conversations","body":"Board games on the shelf, books within reach, and tables made for lingering. Bring your people.","needs_owner_review":true}]}'::jsonb) on conflict (key) do nothing;
insert into website_settings (key, value) values ('notifications', '{"admin_emails":[],"admin_whatsapp":[],"email_enabled":false,"whatsapp_enabled":false}'::jsonb) on conflict (key) do nothing;
